class SegmentImagesThread(QtCore.QThread):

    progress = QtCore.pyqtSignal(int)

    show_original_anno = QtCore.pyqtSignal(np.ndarray)
    show_postprocessed_anno = QtCore.pyqtSignal(np.ndarray) 
    save_postprocessed_anno = QtCore.pyqtSignal(pd.DataFrame, str) 

    def __init__(self, image_files, predictor, model_path, annotations_df, csv_file, directory):
       
        QtCore.QThread.__init__(self)

        self.image_files = image_files

        self.predictor = predictor

        self.model_path = model_path

        self.annotations_df = annotations_df

        self.csv_file = csv_file

        self.directory = directory

        # self.predictor = predictor

        self.segmentImages = PostProcessing()

        # self.segmentImages.progress.connect(self.send_progress)

    def run(self):

        self.current_index = 0

        for image_file in self.image_files:

            if image_file.endswith(('.jpg', '.png', '.jpeg', '.tiff', '.dm3', '.dm4')):
            
                print('Processing image: ', self.image_files[self.current_index])
                
                self.image, self.nm_to_px, annotated_image = self.segmentImages.get_current_anno(self.image_files, self.current_index, self.annotations_df)
                #self.segmentImages.show_current_image(annotated_image)  
                self.show_original_anno.emit(annotated_image)

                self.all_contours, self.segmented_image = self.segmentImages.segment_sliding_window(self.image, self.predictor, self.nm_to_px)

                self.show_postprocessed_anno.emit(self.segmented_image)

                self.annotations_df = self.segmentImages.update_results_csv(self.image_files, self.model_path, self.current_index, self.all_contours, self.annotations_df, self.csv_file, self.segmented_image, self.nm_to_px, self.directory)

                self.save_postprocessed_anno.emit(self.annotations_df, self.csv_file)

                self.current_index += 1
        
        # dir_df, dir_to_save = self.segmentImages.segment_all_imgs_in_dir(self.dir_to_segment, self.predictor)

        # self.finished_label.emit(dir_df, dir_to_save)

