    def loadImage(self):

        try:
            
            # Get supported image formats
            supported_formats = [fmt.data().decode().lower() for fmt in QtGui.QImageReader.supportedImageFormats()]
            extensions = [f"*.{fmt}" for fmt in supported_formats]
            
            # Find all image files in directory
            self.image_files = []
            for ext in extensions:
                self.image_files.extend(sorted(
                    [os.path.join(self.directory, f) for f in os.listdir(self.directory) if f.lower().endswith(ext[1:])],
                    key=str.lower
                ))
            
            if self.image_files:
                self.current_index = 0
                self.update_buttons()
                _, _, annotated_image = self.get_current_anno(self.image_files, self.current_index, self.annotations_df)
                self.show_current_image(annotated_image)  
            else:
                #self.labelPlotImage.setText("No images found in selected directory")
                self.pushButtonPrevious.setEnabled(False)
                self.pushButtonNext.setEnabled(False)

        except Exception as e:
            self.show_error_message(f"Error loading images:\n\n{str(e)}")

    def get_current_anno(self, image_files, current_index, annotations_df):

        self.image_files = image_files

        self.current_index = current_index

        self.annotations_df = annotations_df

        if self.image_files:

            img_path = self.image_files[self.current_index]
            #Get image name to find it in csv
            _, img_name = os.path.split(img_path)

            self.image, self.nm_to_px = Utils().read_image(img_path) # Read image, including .dm files

            if self.annotations_df is not None:

                annotated_image = np.copy(self.image) 

                # Check if annotation is available for image
                if img_name in self.annotations_df.FileName.values.tolist():

                    #image, nm_to_px = Utils().read_image(img_path) # Read image, including .dm files

                    #Get contour value for this filename
                    contours = self.annotations_df.loc[self.annotations_df["FileName"] == img_name, "contours"]
                    # Plot each polygon
                    
                    # if contours.empty or contours.isna().all():
                        
                    #     annotated_image = self.image.copy()

                    # else:

                    for polygon in contours:

                        if pd.isna(polygon).all():
                            print("Skipping NaN polygon")
                            continue

                        # Step 1: Handle string representations of lists (e.g., "[[x1, y1], [x2, y2]]")
                        if isinstance(polygon, str):
                            try:
                                # Convert string to a Python list using ast.literal_eval
                                polygon = ast.literal_eval(polygon)
                            except (SyntaxError, ValueError):
                                print(f"Failed to parse string polygon: {polygon}")
                                continue

                        # Convert polygon coordinates to a NumPy array
                        points = np.array(polygon)

                        x = points[:, 0]  # Extract x-coordinates
                        y = points[:, 1]  # Extract y-coordinates
                        draw_polygon = np.column_stack((x, y)).astype(np.int32)   

                        # Draw the bumpy circle contour, bgr format
                        cv2.polylines(annotated_image, [draw_polygon], isClosed=True, color=(255, 0, 0), thickness=10)
            else:

                annotated_image = self.image.copy()

        return self.image, self.nm_to_px, annotated_image
    
